import { createHash } from 'crypto';
import { materializeTextFiles } from './retainedTextFiles';
import fs from 'fs/promises';
import path from 'path';
import { GuidanceError, type GuidanceDocument } from '../types/guidance';
import {
  GuidanceReferencesSchema,
  type GuidanceReference,
} from '../types/guidance-references';
import { errorMessage } from '../utils/errorMessage';

const digest = (text: string | Buffer): string =>
  createHash('sha256').update(text).digest('hex');

const materializeReference = async (
  reference: GuidanceReference,
  directory: string,
): Promise<GuidanceReference> => {
  if (reference.kind === 'directory' || !reference.files?.length)
    return reference;
  const files = [...reference.files].sort((first, second) =>
    first.name < second.name ? -1 : Number(first.name > second.name),
  );
  const treeDigest = digest(
    JSON.stringify(files.map(({ name, content }) => [name, content])),
  );
  if (reference.digest !== undefined && reference.digest !== treeDigest)
    throw new Error('Reference digest does not match retained content');
  for (const file of files)
    if (file.sha256 !== undefined && file.sha256 !== digest(file.content))
      throw new Error('Reference file digest does not match retained content');
  const destination = await materializeTextFiles({ files, directory });
  return {
    ...reference,
    digest: treeDigest,
    files: reference.files.map((file) => ({
      ...file,
      sha256: digest(file.content),
      path: path.join(destination, file.name),
    })),
  };
};

export const materializeGuidanceReferences = async (args: {
  documents: GuidanceDocument[];
  dataDirectory: string;
}): Promise<GuidanceDocument[]> => {
  if (
    !args.documents.some((document) =>
      document.references?.some(
        (reference) =>
          reference.kind !== 'directory' && reference.files?.length,
      ),
    )
  )
    return args.documents;
  try {
    await fs.mkdir(args.dataDirectory, { recursive: true, mode: 0o700 });
    const directory = path.join(
      await fs.realpath(args.dataDirectory),
      'guidance-references',
    );

    const documents = [];
    for (const document of args.documents) {
      if (document.references === undefined) {
        documents.push(document);
        continue;
      }
      const references = [];
      for (const reference of GuidanceReferencesSchema.parse(
        document.references,
      ))
        references.push(await materializeReference(reference, directory));
      documents.push({ ...document, references });
    }
    return documents;
  } catch (error) {
    throw new GuidanceError(
      'guidance_asset_invalid',
      `Saved context reference: ${errorMessage(error, 'Could not retain native files')}`,
    );
  }
};
